CREATE TABLE IF NOT EXISTS audit_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_user_id BIGINT,actor_email VARCHAR(255) NOT NULL DEFAULT 'system',action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(100),details VARCHAR(1000) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_audit_created_at ON audit_events(created_at);